const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;

    const L = parseInt(input[0], 10);
    const C = parseInt(input[1], 10);

    const grid = [];
    let startR = -1, startC = -1;

    for (let i = 0; i < L; i++) {
        const row = input[2 + i].split('');
        grid.push(row);
        for (let j = 0; j < C; j++) {
            if (row[j] === 'o') {
                startR = i;
                startC = j;
            }
        }
    }

    const visited = Array.from({ length: L }, () => Array(C).fill(false));
    visited[startR][startC] = true;

    const dr = [-1, 1, 0, 0];
    const dc = [0, 0, -1, 1];

    let currR = startR;
    let currC = startC;

    while (true) {
        let moved = false;
        for (let d = 0; d < 4; d++) {
            const nr = currR + dr[d];
            const nc = currC + dc[d];

            if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                if (!visited[nr][nc] && grid[nr][nc] === 'H') {
                    visited[nr][nc] = true;
                    currR = nr;
                    currC = nc;
                    moved = true;
                    break;
                }
            }
        }
        if (!moved) {
            break;
        }
    }

    console.log(`${currR + 1} ${currC + 1}`);
}

main();
